(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.RepoCommunity=factory()})(globalThis,function(){
'use strict';
const WINDOW=30*86400000;
function postUrl(p){try{const u=new URL(p.url);if(u.protocol!=='https:'||u.username||u.password)return null;if(p.source==='hackernews'&&u.hostname==='news.ycombinator.com'&&u.pathname==='/item'&&/^\d+$/.test(u.searchParams.get('id')||''))return u.href;if(p.source==='bluesky'&&u.hostname==='bsky.app'&&/^\/profile\/[^/]+\/post\/[a-zA-Z0-9]+$/.test(u.pathname))return u.href}catch{}return null}
function validPost(p,now=Date.now()){const date=Date.parse(p?.publishedAt);return p&&typeof p.full==='string'&&/^[\w.-]+\/[\w.-]+$/.test(p.full)&&typeof p.id==='string'&&postUrl(p)&&Number.isFinite(date)&&date<=now+300000&&now-date<=WINDOW}
function posts(repo,now=Date.now()){return (repo.communityPosts||[]).filter(p=>validPost(p,now)).sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt))}
function interest(p,now){const raw=p.source==='hackernews'?Math.log1p(Math.max(0,p.points||0))+.5*Math.log1p(Math.max(0,p.comments||0)):Math.log1p(Math.max(0,p.likes||0))+.6*Math.log1p(Math.max(0,p.replies||0))+.3*Math.log1p(Math.max(0,p.reposts||0));return (1+raw)/(1+Math.max(0,now-Date.parse(p.publishedAt))/(3*86400000))}
function rank(repos,now=Date.now()){const items=repos.map(repo=>({repo,evidence:posts(repo,now)})).filter(x=>x.evidence.length),groups=new Map();for(const item of items){item.scores=new Map();for(const p of item.evidence)item.scores.set(p.source,Math.max(item.scores.get(p.source)||0,interest(p,now)));for(const [source,score]of item.scores){if(!groups.has(source))groups.set(source,[]);groups.get(source).push(score)}}for(const scores of groups.values())scores.sort((a,b)=>a-b);for(const item of items){let best=0;for(const [source,score]of item.scores){const scores=groups.get(source);best=Math.max(best,(scores.indexOf(score)+scores.lastIndexOf(score)+1)/(2*scores.length))}const authors=new Set(item.evidence.map(p=>p.author?`${p.source}:${p.author}`:`${p.source}:unknown`));item.score=best+.12*Math.log1p(Math.min(authors.size,10))+.2/(1+Math.max(0,now-Date.parse(item.evidence[0].publishedAt))/86400000)}return items.sort((a,b)=>b.score-a.score||a.repo.full.localeCompare(b.repo.full)).map(x=>x.repo)}
function attach(repos,mentions,now=Date.now()){const map=new Map();for(const p of mentions||[]){if(!validPost(p,now))continue;const key=p.full.toLowerCase();if(!map.has(key))map.set(key,new Map());map.get(key).set(p.source+':'+p.id,p)}return repos.map(r=>({...r,communityPosts:[...(map.get(r.full.toLowerCase())?.values()||[])]}))}
return {WINDOW,postUrl,validPost,posts,rank,attach};
});
